// FUNCTION: BFME2 0x002D3002 size=197 name=?OnBttnSpellStore@AptPalantir@@QAEXPBD@Z evidence=N:ledger tier=A
void AptPalantir::OnBttnSpellStore(const char *)
{
	// The Apt button presses the control bar's general button.
	static NameKeyType buttonID = TheNameKeyGenerator->nameToKey("ControlBar.wnd:ButtonGeneral");
	GameWindow *button = TheWindowManager->winGetWindowFromId(NULL, buttonID);
	if (button != NULL)
	{
		WinInstanceData *instData = button->winGetInstanceData();
		if (instData != NULL)
		{
			int mode = g_bfmeAptWindowManager->getUnk0x318();
			GameWindow *owner = instData->m_owner;
			TheWindowManager->winSendSystemMsg(owner, mode == 2 ? 0x4009 : 0x4008, (unsigned int)button, button->winGetWindowId());
			m_unk0xE4 = false;
		}
	}
}

